// Tiny audio manager. Plays /public/audio/*.mp3 if present; silent no-op if missing.
// Files are generated by scripts/generate-audio.mjs and live in public/audio/.
import type { Element as GameElement } from "./game/critters";

export type SfxName =
  | "hit"
  | "catch"
  | "encounter"
  | "levelup"
  | "hit-ember"
  | "hit-aqua"
  | "hit-leaf"
  | "hit-normal"
  | "ui-click"
  | "ui-confirm"
  | "ui-cancel"
  | "summon-shimmer";

const VOL: Record<SfxName, number> = {
  hit: 0.5,
  catch: 0.6,
  encounter: 0.5,
  levelup: 0.6,
  "hit-ember": 0.5,
  "hit-aqua": 0.5,
  "hit-leaf": 0.5,
  "hit-normal": 0.5,
  "ui-click": 0.35,
  "ui-confirm": 0.45,
  "ui-cancel": 0.4,
  "summon-shimmer": 0.55,
};

/** Element-specific hit sound for a move's element. */
export function hitSfxFor(element: GameElement): SfxName {
  switch (element) {
    case "Ember":
      return "hit-ember";
    case "Aqua":
      return "hit-aqua";
    case "Leaf":
      return "hit-leaf";
    default:
      return "hit-normal";
  }
}

export type MusicContext = "field" | "battle";

const MUSIC_SRC: Record<MusicContext, string> = {
  field: "/audio/bgm-town.m4a",
  battle: "/audio/bgm-battle.m4a",
};
/** The original single track, kept as the fallback if a themed loop is missing. */
const FALLBACK_MUSIC = "/audio/bgm.mp3";
const MUSIC_VOLUME = 0.32;

/** Ordered sources to try for a music context. */
export function musicSources(context: MusicContext): string[] {
  return [MUSIC_SRC[context], FALLBACK_MUSIC];
}

// small pool per sound so rapid repeats don't cut each other off
const pools: Partial<Record<SfxName, HTMLAudioElement[]>> = {};

function pool(name: SfxName): HTMLAudioElement[] {
  if (!pools[name]) {
    pools[name] = Array.from({ length: 3 }, () => {
      const a = new Audio(`/audio/${name}.mp3`);
      a.volume = VOL[name];
      a.preload = "auto";
      return a;
    });
  }
  return pools[name]!;
}

// Sound state: `started` flips on the first user gesture, `enabled` is the player's mute toggle.
let started = false;
let enabled = true;
let context: MusicContext = "field";
let music: HTMLAudioElement | null = null;

export function sfx(name: SfxName) {
  if (!enabled) return; // the Sound toggle mutes every effect, not just music
  const p = pool(name);
  const a = p.find((x) => x.paused || x.ended) ?? p[0];
  try {
    a.currentTime = 0;
    void a.play().catch(() => {});
  } catch {
    /* file missing or blocked: silent */
  }
}

export function uiSfx(name: "ui-click" | "ui-confirm" | "ui-cancel") {
  sfx(name);
}

function loadTrack(sources: string[]): HTMLAudioElement {
  let i = 0;
  const a = new Audio(sources[i]);
  a.loop = true;
  a.volume = MUSIC_VOLUME;
  a.addEventListener("error", () => {
    // themed loop missing: fall back to the next source and keep playing if we should be
    if (i + 1 >= sources.length) return;
    i += 1;
    a.src = sources[i];
    if (started && enabled && music === a) void a.play().catch(() => {});
  });
  return a;
}

/**
 * Gapless loop buffer: equal-power crossfade of the last `fadeSec` into the first `fadeSec`, then
 * drop the tail so the end flows straight into the start. Returns new channel arrays of length
 * `length - fade`. Pure, so it is unit-tested.
 */
export function crossfadeLoop(channels: Float32Array[], sampleRate: number, fadeSec: number): Float32Array[] {
  return channels.map((ch) => {
    const n = Math.min(Math.floor(fadeSec * sampleRate), Math.floor(ch.length / 2));
    const out = ch.slice(0, ch.length - n);
    for (let i = 0; i < n; i++) {
      const t = ((i + 0.5) / n) * (Math.PI / 2);
      out[i] = ch[i] * Math.sin(t) + ch[ch.length - n + i] * Math.cos(t);
    }
    return out;
  });
}

const LOOP_FADE_SEC = 3;
let audioCtx: AudioContext | null = null;
let webGain: GainNode | null = null;
let webSource: AudioBufferSourceNode | null = null;
let webToken = 0;
const loopBuffers: Partial<Record<MusicContext, Promise<AudioBuffer>>> = {};

function loadLoop(ctx: AudioContext, c: MusicContext): Promise<AudioBuffer> {
  return (loopBuffers[c] ??= fetch(MUSIC_SRC[c])
    .then((r) => {
      if (!r.ok) throw new Error(`music ${r.status}`);
      return r.arrayBuffer();
    })
    .then((bytes) => ctx.decodeAudioData(bytes))
    .then((buf) => {
      const chans = Array.from({ length: buf.numberOfChannels }, (_, i) => buf.getChannelData(i));
      const looped = crossfadeLoop(chans, buf.sampleRate, LOOP_FADE_SEC);
      const out = ctx.createBuffer(looped.length, looped[0].length, buf.sampleRate);
      looped.forEach((d, i) => out.copyToChannel(d as Float32Array<ArrayBuffer>, i));
      return out;
    })
    .catch((e) => {
      delete loopBuffers[c]; // allow a retry later
      throw e;
    }));
}

function stopWeb() {
  webToken++;
  try {
    webSource?.stop();
  } catch {
    /* already stopped */
  }
  webSource = null;
}

/** WebAudio looping playback. Resolves false when unsupported or the file cannot be decoded. */
async function playWeb(c: MusicContext): Promise<boolean> {
  const Ctor: typeof AudioContext | undefined =
    window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
  if (!Ctor) return false;
  try {
    if (!audioCtx) {
      audioCtx = new Ctor();
      webGain = audioCtx.createGain();
      webGain.gain.value = MUSIC_VOLUME;
      webGain.connect(audioCtx.destination);
    }
    stopWeb();
    const token = webToken;
    const buf = await loadLoop(audioCtx, c);
    if (token !== webToken || !enabled || context !== c) return true; // superseded or muted meanwhile
    await audioCtx.resume();
    const src = audioCtx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    src.connect(webGain!);
    src.start();
    webSource = src;
    return true;
  } catch {
    return false;
  }
}

/** Starts (or restarts) the track for the current context if sound is on. */
function playCurrent() {
  if (!started || !enabled) return;
  void playWeb(context).then((ok) => {
    if (ok) return;
    // WebAudio unavailable or decode failed: plain HTMLAudio, which can also fall back to bgm.mp3
    music = trackFor(context);
    void music.play().catch(() => {
      started = false; // autoplay blocked: allow the next gesture to try again
    });
  });
}

const tracks: Partial<Record<MusicContext, HTMLAudioElement>> = {};

function trackFor(ctx: MusicContext): HTMLAudioElement {
  return (tracks[ctx] ??= loadTrack(musicSources(ctx)));
}

function pauseAllMusic() {
  stopWeb();
  music?.pause();
}

export function startMusic() {
  started = true;
  playCurrent();
}

/** Switch between the field and battle loops. Never starts music while muted or before a gesture. */
export function setMusicContext(next: MusicContext) {
  if (next === context) return;
  context = next;
  if (!started) return; // startMusic() hasn't run yet; it will pick up the context
  pauseAllMusic();
  if (music) music.currentTime = 0;
  playCurrent();
}

export function toggleMusic(): boolean {
  if (!started) {
    enabled = true;
    startMusic();
    return true;
  }
  enabled = !enabled;
  if (enabled) playCurrent();
  else pauseAllMusic();
  return enabled;
}

/** Click/confirm/cancel sounds for every button, via one delegated listener. */
const CANCEL = ".summon-close, .io-close, .sw-cancel, .dex-close, .guide-close, .summon-discard, [data-act=leave]";
const CONFIRM = ".summon-go, .io-primary, .victory-btn, .starter, .shop-buy";
export function installUiSounds(root: Document = document) {
  root.addEventListener("click", (e) => {
    const btn = (e.target as Element | null)?.closest?.("button");
    if (!btn || (btn as HTMLButtonElement).disabled || btn.classList.contains("mute")) return;
    uiSfx(btn.matches(CANCEL) ? "ui-cancel" : btn.matches(CONFIRM) ? "ui-confirm" : "ui-click");
  });
}
